import{_ as e,o as a,c as i,a0 as n}from"./chunks/framework.BQGW-Zpy.js";const u=JSON.parse('{"title":"Testing & Validation","description":"","frontmatter":{},"headers":[],"relativePath":"analysis/testing-validation.md","filePath":"analysis/testing-validation.md"}'),o={name:"analysis/testing-validation.md"};function r(s,t,d,l,c,h){return a(),i("div",null,[...t[0]||(t[0]=[n('<h1 id="testing-validation" tabindex="-1">Testing &amp; Validation <a class="header-anchor" href="#testing-validation" aria-label="Permalink to &quot;Testing &amp; Validation&quot;">​</a></h1><h2 id="what-s-actually-tested-and-passes" tabindex="-1">What&#39;s actually tested, and passes <a class="header-anchor" href="#what-s-actually-tested-and-passes" aria-label="Permalink to &quot;What&#39;s actually tested, and passes&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Suite</th><th>Runner</th><th>Coverage</th></tr></thead><tbody><tr><td>Unit (14 tests)</td><td>Node&#39;s built-in <code>node --test</code></td><td>Canonical hashing (order-independence, tamper sensitivity), pseudonymous reference generation, corridor routing decisions</td></tr><tr><td>Unit (26 tests)</td><td>Vitest + Supertest</td><td>Same hashing/routing logic ported to Vitest, plus real HTTP-level tests against the actual Express app: health check, 404 handling, community-post validation (rejects a missing code, an unrecognized code, a too-short message), plus 5 tests for the HSS completion-schedule flow (creation, rejection of an incomplete record, and — the critical case — that the same partner key signing twice does not fake a second signature)</td></tr><tr><td>End-to-end (6 tests)</td><td>Playwright, real Chromium</td><td>Home page loads with the core promise visible; Send Money form has no wallet/private-key/seed-phrase text anywhere; Tamper Demo loads with an initial hash match; tampering the record and re-verifying genuinely flips the UI to a mismatch; Community page shows the code requirement; the app shell&#39;s splash screen appears before entry</td></tr></tbody></table><p>Run them: <code>npm test</code> (unit), <code>npm run test:vitest</code> (Vitest + Supertest), <code>npm run test:e2e</code> (Playwright, after <code>npx playwright install chromium</code>).</p><h2 id="what-s-verified-against-the-real-network-not-simulated" tabindex="-1">What&#39;s verified against the real network, not simulated <a class="header-anchor" href="#what-s-verified-against-the-real-network-not-simulated" aria-label="Permalink to &quot;What&#39;s verified against the real network, not simulated&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Behavior</th><th>Verified how</th></tr></thead><tbody><tr><td>Compliance record → anchor</td><td>Real Hedera testnet transaction, confirmed directly against the public Mirror Node (topic ID, transaction ID, consensus timestamp all independently fetched and checked, not asserted)</td></tr><tr><td>Mirror Node query</td><td>The same record is retrievable from <code>testnet.mirrornode.hedera.com</code> by anyone, without going through this project&#39;s own API</td></tr><tr><td>Alter the off-chain record, then verify</td><td>Verification <strong>fails</strong> (hash mismatch), confirmed live in the Playwright suite above, not just described</td></tr><tr><td>Verify endpoint&#39;s own real-network check</td><td>Tries a Mirror Node message lookup by sequence number first, falls back to a Mirror Node transaction-ID lookup if that doesn&#39;t resolve, both independently confirmed working against real transactions during this project&#39;s own testing</td></tr></tbody></table><h2 id="scope-this-project-does-not-cover-yet" tabindex="-1">Scope this project does not cover yet <a class="header-anchor" href="#scope-this-project-does-not-cover-yet" aria-label="Permalink to &quot;Scope this project does not cover yet&quot;">​</a></h2><ul><li><strong>Webhook signature verification.</strong> The current fiat on-ramp (<code>POST /api/payments</code>) is a mock endpoint returning a fixed success response, not a real Stripe integration with signed webhooks. Testing signature verification, replay rejection, or webhook-triggered settlement would require that integration to exist first, see <a href="./known-limitations.html">Known Limitations</a>.</li><li><strong>Payout-partner failure/reconciliation handling.</strong> Same reasoning, no real payout-partner (e.g. Flutterwave) integration exists yet to test failure handling against.</li><li><strong>Load/concurrency testing.</strong> Not attempted at this project&#39;s current scale.</li></ul>',8)])])}const m=e(o,[["render",r]]);export{u as __pageData,m as default};
